        this._notify('SIGNED_OUT', null);
        return { error: null };
    },

    onAuthStateChange(callback) {
        this._listeners.push(callback);
        // Return unsubscribe
        return { data: { subscription: { unsubscribe: () => { } } } };
    },

    _notify(event, session) {
        this._listeners.forEach(cb => cb(event, session));
    }
